<?php
namespace App\Http\Controllers\Accounting;use App\Http\Controllers\Controller;use App\Models\{Account,Folio,JournalEntry,NightAudit,SupplierInvoice};use App\Services\Accounting\AccountingService;
class AccountingDashboardController extends Controller{public function __invoke(AccountingService $svc){$p=auth()->user()->property_id;$income=(float)\App\Models\JournalLine::join('journal_entries','journal_entries.id','=','journal_lines.journal_entry_id')->join('accounts','accounts.id','=','journal_lines.account_id')->where('journal_entries.property_id',$p)->where('journal_entries.status','posted')->where('accounts.type','income')->selectRaw('COALESCE(SUM(journal_lines.credit-journal_lines.debit),0) t')->value('t');return view('accounting.dashboard',['income'=>$income,'receivables'=>Folio::where('property_id',$p)->where('balance','>',0)->sum('balance'),'payables'=>SupplierInvoice::where('property_id',$p)->whereIn('status',['unpaid','part_paid'])->selectRaw('COALESCE(SUM(total_amount-paid_amount),0) t')->value('t'),'journals'=>JournalEntry::with('lines.account')->where('property_id',$p)->latest()->limit(8)->get(),'audit'=>NightAudit::where('property_id',$p)->latest('business_date')->first()]);}}
